var n=`0121-beef-stroganoff`;var i=`world-0121`;var o=`RU`;var s=`eastern-europe`;var a=4;var r=29;var u={en:`Beef Stroganoff`,ua:`Бефстроганов`};var l={en:`A classic dish from Russia, featuring beef sirloin, yellow onion, button mushroom, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Росія. Основні складники: яловичий сирлойн, жовта цибуля, печериця, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`beef-sirloin`,620,`g`],[`unsalted-butter`,35,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,180,`g`],[`button-mushroom`,300,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 7 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 7 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:7,i:[[`all-purpose-flour`,35,`g`],[`beef-stock`,380,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`sour-cream`,220,`g`],[`dijon-mustard`,20,`g`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]}];var g={slug:n,id:i,country:`RU`,region:s,servings:4,minutes:29,title:u,text:l,steps:d};export{o as country,g as default,i as id,r as minutes,s as region,a as servings,n as slug,d as steps,l as text,u as title};